"""Independent brute-force reference for PROTOCOL.md semantics (small random cases)."""
import json, random, subprocess, sys
from collections import deque

# ---------- topology: templates (footprints + domains) from PROTOCOL.md text ----------

def bfs_dist(adj, src):
    dist = [-1]*len(adj); dist[src] = 0; q = deque([src])
    while q:
        u = q.popleft()
        for v in adj[u]:
            if dist[v] < 0:
                dist[v] = dist[u]+1; q.append(v)
    return dist

def on_shortest_cache(dist_s, dist_d, cache):
