            out.append(u)
    return out

def make_topology(topo):
    """returns num_nodes, templates=[(src,dst,footprint,domain)], cache[]"""
    kind = topo[0]
    if kind == 'clos':
        k, scope, intra = topo[1], topo[2], topo[3]
        r = k//2; T = k*r; N = k*k
        cache = [True]*N
        pod = lambda t: t//r
        templates = []
        for src in range(T):
            for dst in range(T):
                if src == dst: continue
                if not intra and pod(src) == pod(dst): continue
                fp = {src, dst}
                if pod(src) == pod(dst):
                    fp |= {T + pod(src)*r + o for o in range(r)}
                else:
                    fp |= {T + pod(src)*r + o for o in range(r)}
                    fp |= {T + pod(dst)*r + o for o in range(r)}
                dom = src if scope == 'tor' else pod(src)
                templates.append((src, dst, sorted(fp), dom))
        return N, templates, cache
    if kind == 'leaf-spine':
        leaves, spines = topo[1], topo[2]
        N = leaves+spines
        cache = [i < leaves for i in range(N)]
        templates = []
        for src in range(leaves):
            for dst in range(leaves):
                if src == dst: continue
                templates.append((src, dst, [src, dst], src))
        return N, templates, cache
    if kind in ('torus2d', 'torus3d'):
        n = topo[1]; scope = topo[2]
        dim = 2 if kind == 'torus2d' else 3
        N = n**dim
        adj = [[] for _ in range(N)]
        def nid(coords):
            if dim == 2: return coords[1]*n + coords[0]
            return (coords[2]*n + coords[1])*n + coords[0]
        for node in range(N):
            c = []
            x = node
            for _ in range(dim):
                c.append(x % n); x //= n
            for ax in range(dim):
                for dlt in (1, -1):
                    cc = list(c); cc[ax] = (cc[ax]+dlt) % n
                    adj[node].append(nid(cc))
        cache = [True]*N
        templates = []
        for src in range(N):
            ds = bfs_dist(adj, src)
            for dst in range(N):
                if src == dst: continue
                dd = bfs_dist(adj, dst)
                fp = [u for u in range(N) if ds[u]+dd[u] == ds[dst]]
                dom = src if scope == 'host' else src//n
                templates.append((src, dst, fp, dom))
        return N, templates, cache
    if kind == 'dragonfly':
        g, a, h, scope = topo[1], topo[2], topo[3], topo[4]
        N = g*a
        adj = [[] for _ in range(N)]
        rid = lambda gr, i: gr*a+i
        for gr in range(g):
            for i in range(a):
                for j in range(i+1, a):
                    adj[rid(gr,i)].append(rid(gr,j)); adj[rid(gr,j)].append(rid(gr,i))
        for g1 in range(g):
            for g2 in range(g1+1, g):
                delta = (g2-g1) % g
                rd = (g-delta) % g
                u = rid(g1, (delta-1)//h); v = rid(g2, (rd-1)//h)
                adj[u].append(v); adj[v].append(u)
        cache = [True]*N
        templates = []
        for src in range(N):
            ds = bfs_dist(adj, src)
            for dst in range(N):
                if src == dst: continue
                dd = bfs_dist(adj, dst)
                fp = [u for u in range(N) if ds[u]+dd[u] == ds[dst]]
                if scope == 'router': dom = src
                elif scope == 'group': dom = src//a
                else: dom = src*g + (dst//a)
                templates.append((src, dst, fp, dom))
        return N, templates, cache
    if kind == 'dragonfly-plus':
        g, l, s, h, dense, scope = topo[1], topo[2], topo[3], topo[4], topo[5], topo[6]
        sw = l+s; N = g*sw
        adj = [[] for _ in range(N)]
        def leaf(gr, i): return gr*sw+i
        def spine(gr, i): return gr*sw+l+i
        for gr in range(g):
            for i in range(l):
                for p in range(s):
                    adj[leaf(gr,i)].append(spine(gr,p)); adj[spine(gr,p)].append(leaf(gr,i))
        if dense:
            for g1 in range(g):
                for g2 in range(g1+1, g):
                    for p in range(s):
                        adj[spine(g1,p)].append(spine(g2,p)); adj[spine(g2,p)].append(spine(g1,p))
        else:
            for g1 in range(g):
                for g2 in range(g1+1, g):
                    delta = (g2-g1) % g
                    rd = (g-delta) % g
                    u = spine(g1, (delta-1)//h); v = spine(g2, (rd-1)//h)
                    adj[u].append(v); adj[v].append(u)
        cache = [True]*N
        templates = []
        for gr in range(g):
            for i in range(l):
                src = leaf(gr, i)
                ds = bfs_dist(adj, src)
                for gr2 in range(g):
                    for j in range(l):
                        dst = leaf(gr2, j)
                        if src == dst: continue
                        dd = bfs_dist(adj, dst)
                        fp = [u for u in range(N) if ds[u]+dd[u] == ds[dst]]
                        dom = gr if scope == 'group' else gr*l + i
                        templates.append((src, dst, fp, dom))
        return N, templates, cache
    raise ValueError(kind)

# ---------- reference ledger ----------

class Ref:
    def __init__(self, N, templates, cache, caps, groups, tasks):
        self.N = N
        self.templates = templates
        self.cache = cache
        self.caps = list(caps)
        self.groups = [list(x) for x in groups]   # [quota, budget]
        self.tasks = [list(x) for x in tasks]     # [tpl, grp, w, cls, pin]
        self.revision = 0

    def fp(self, tpl): return self.templates[tpl][2]
    def dom(self, tpl): return self.templates[tpl][3]

    def legal(self):
        G = len(self.groups)
        for g in range(G):
            members = [t for t in self.tasks if t[1] == g]
            if not members: continue
            pairs = {(self.dom(t[0]), t[3]) for t in members}
            if len(pairs) != 1: return False
            quota, budget = self.groups[g]
            if quota == 0: return False
            if sum(t[2] for t in members) > quota*budget: return False
        usage = self.usage()
        return all(usage[v] <= self.caps[v] for v in range(self.N))

    def usage(self):
        usage = [0]*self.N
        for g in range(len(self.groups)):
            members = [t for t in self.tasks if t[1] == g]
            if not members: continue
            nodes = set()
            for t in members: nodes |= set(self.fp(t[0]))
            for v in nodes: usage[v] += self.groups[g][0]
        return usage

    def certificate(self, q):
        active = sum(1 for g in range(len(self.groups)) if any(t[1] == g for t in self.tasks))
        usage = self.usage()
        slots = sum(usage)
        weight = sum(t[2] for t in self.tasks)
        pins = sum(t[4] for t in self.tasks)
        grows = []
        for gid in q['groups']:
            members = [t for t in self.tasks if t[1] == gid]
            if members:
                pairs = {(self.dom(t[0]), t[3]) for t in members}
                assert len(pairs) == 1
                dom, cls = next(iter(pairs))
                nodes = set()
                for t in members: nodes |= set(self.fp(t[0]))
                grows.append([gid, len(members), sum(t[2] for t in members),
                              self.groups[gid][0], self.groups[gid][1], len(nodes), dom, cls])
            else:
                grows.append([gid, 0, 0, self.groups[gid][0], self.groups[gid][1], 0, -1, -1])
        nrows = [[v, usage[v], self.caps[v]] for v in q['nodes']]
        trows = [[t, self.tasks[t][1], self.tasks[t][0], self.tasks[t][2], self.tasks[t][3], self.tasks[t][4]] for t in q['tasks']]
        return {'totals': [active, slots, weight, pins], 'groups': grows, 'nodes': nrows, 'tasks': trows}

    def transact(self, revision, edits, query):
        if revision != self.revision:
            return {'accepted': False, 'revision': self.revision, 'violations': None,
                    'certificate': self.certificate(query)}
        # proposal: field assignments, last value wins
        prop = {
            'tasks': [list(t) for t in self.tasks],
            'groups': [list(g) for g in self.groups],
            'caps': list(self.caps),
        }
        for op, idx, val in edits:
            if op == 'move': prop['tasks'][idx][1] = val
            elif op == 'weight': prop['tasks'][idx][2] = val
            elif op == 'class': prop['tasks'][idx][3] = val
            elif op == 'bind': prop['tasks'][idx][0] = val
            elif op == 'pin': prop['tasks'][idx][4] = val
            elif op == 'quota': prop['groups'][idx][0] = val
            elif op == 'budget': prop['groups'][idx][1] = val
            elif op == 'cap': prop['caps'][idx] = val
        # violations on FINAL proposal
        pr = Ref(self.N, self.templates, self.cache, prop['caps'], prop['groups'], prop['tasks'])
        # capacity
        pu = pr.usage()
        capv = sum(1 for v in range(self.N) if pu[v] > pr.caps[v])
        # mixed
        G = len(self.groups)
        mixed = 0; work = 0
        for g in range(G):
            members = [t for t in pr.tasks if t[1] == g]
            if not members: continue
            pairs = {(pr.dom(t[0]), t[3]) for t in members}
            if len(pairs) > 1: mixed += 1
            quota, budget = pr.groups[g]
            if quota == 0 or sum(t[2] for t in members) > quota*budget: work += 1
        # pins: protected = tasks pinned at beginning; protects group, template,
        # weight, class and its OLD group's quota
        pins_v = 0
        for t0 in self.tasks:
            if not t0[4]: continue
            tid = self.tasks.index(t0)  # wrong with duplicates; use enumerate below
        for tid, t0 in enumerate(self.tasks):
            if not t0[4]: continue
            t1 = pr.tasks[tid]
            oldg = t0[1]
            quota_changed = pr.groups[oldg][0] != self.groups[oldg][0]
            fields_changed = (t1[1] != t0[1] or t1[0] != t0[0] or t1[2] != t0[2] or t1[3] != t0[3])
            if fields_changed or quota_changed:
                pins_v += 1
        violations = [capv, mixed, work, pins_v]
        accepted = violations == [0, 0, 0, 0]
        if accepted:
            self.tasks = pr.tasks
            self.groups = pr.groups
            self.caps = pr.caps
            self.revision += 1
        return {'accepted': accepted, 'revision': self.revision,
                'violations': violations, 'certificate': self.certificate(query)}

# ---------- random session generator ----------

def gen_session(rng, topo):
    N, templates, cache = make_topology(topo)
    T = len(templates)
    G = rng.randint(1, 5)
    groups = [[rng.randint(0, 6), rng.randint(1, 20)] for _ in range(G)]
    D = rng.randint(0, 12)
    tasks = []
    for _ in range(D):
        tpl = rng.randrange(T)
        # keep all members of a group uniform in (dom,class) initially
        tasks.append([tpl, 0, rng.randint(1, 10), rng.randint(0, 4), rng.randint(0, 1)])
    # assign groups but ensure uniform (dom, class) per group
    doms = [templates[t[0]][3] for t in tasks]
    for tid in range(D):
        tasks[tid][1] = rng.randrange(G)
    ok = False
    for _ in range(200):
        perm = list(range(D)); rng.shuffle(perm)
        for tid in perm:
            tasks[tid][1] = rng.randrange(G)
        good = True
        for g in range(G):
            pairs = {(templates[t[0]][3], t[3]) for t in tasks if t[1] == g}
            if len(pairs) > 1: good = False; break
        if good: ok = True; break
    if not ok:
        # force uniform class/dom within groups
        for g in range(G):
            members = [t for t in tasks if t[1] == g]
            if members:
                base = (templates[members[0][0]][3], members[0][3])
                for t in members:
                    t[3] = base[1]
    # quotas: make nonempty groups legal
    for g in range(G):
        members = [t for t in tasks if t[1] == g]
        if members:
            load = sum(t[2] for t in members)
            q = groups[g][0]
            b = groups[g][1]
            if q == 0:
                groups[g][0] = q = 1
            if load > q*b:
                groups[g][1] = b = (load + q - 1)//q
    # caps: legal with slack
    ref = Ref(N, templates, cache, [10**9]*N, groups, tasks)
    usage = ref.usage()
    caps = [usage[v] + rng.randint(0, 3) for v in range(N)]
    ref = Ref(N, templates, cache, caps, groups, tasks)
    if not ref.legal():
        return None
    # query
    def q():
        return {'groups': [rng.randrange(G) for _ in range(rng.randint(0, 6))],
                'nodes': [rng.randrange(N) for _ in range(rng.randint(0, 6))],
                'tasks': [rng.randrange(D) for _ in range(rng.randint(0, 6))]}
    transactions = []
    for _ in range(rng.randint(0, 12)):
        edits = []
        for _ in range(rng.randint(0, 8)):
            op = rng.choice(['move','weight','class','bind','pin','quota','budget','cap','move','pin','quota'])
            if op in ('move','weight','class','bind','pin'):
                if D == 0: continue
                tid = rng.randrange(D)
                if op == 'move': val = rng.randrange(G)
                elif op == 'weight': val = rng.randint(1, 15)
                elif op == 'class': val = rng.randint(0, 6)
                elif op == 'bind': val = rng.randrange(T)
                else: val = rng.randint(0, 1)
                edits.append([op, tid, val])
            elif op == 'quota':
                edits.append([op, rng.randrange(G), rng.randint(0, 6)])
            elif op == 'budget':
                edits.append([op, rng.randrange(G), rng.randint(1, 20)])
            else:
                edits.append([op, rng.randrange(N), rng.randint(0, 12)])
        rev = ref.revision if rng.random() < 0.75 else rng.randint(0, 4)
        transactions.append({'revision': rev, 'edits': edits, 'query': q()})
    return {'topology': topo, 'caps': caps, 'groups': groups, 'tasks': tasks,
            'query': q(), 'transactions': transactions}

def run_ref(session):
    N, templates, cache = make_topology(session['topology'])
    ref = Ref(N, templates, cache, session['caps'], session['groups'], session['tasks'])
    assert ref.legal(), 'generator produced illegal initial'
    out = {'nodes': N, 'templates': len(templates),
           'initial': ref.certificate(session['query']),
           'transactions': []}
    for tx in session['transactions']:
        out['transactions'].append(ref.transact(tx['revision'], tx['edits'], tx['query']))
    return out

def run_engine(session):
    req = {'version': 2, 'sessions': [session]}
    data = json.dumps(req, separators=(',', ':'))
    p = subprocess.run([sys.executable, '-B', 'submission/main.py'], input=data.encode(),
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    out = p.stdout.decode()
    try:
        result = json.loads(out)
    except Exception:
        return ('BADOUTPUT', out, p.stderr.decode()[-2000:])
    return result

TOPOS = [
    ['clos', 4, 'tor', 1], ['clos', 4, 'pod', 0], ['clos', 4, 'pod', 1], ['clos', 6, 'tor', 0],
    ['leaf-spine', 2, 1], ['leaf-spine', 4, 3],
    ['torus2d', 3, 'host'], ['torus2d', 3, 'row'], ['torus2d', 4, 'host'],
    ['torus3d', 3, 'host'], ['torus3d', 3, 'line'],
    ['dragonfly', 2, 1, 1, 'router'], ['dragonfly', 3, 1, 2, 'group'], ['dragonfly', 3, 3, 1, 'target'],
    ['dragonfly', 4, 2, 1, 'target'], ['dragonfly', 4, 1, 3, 'router'],
    ['dragonfly-plus', 2, 1, 1, 1, 1, 'group'], ['dragonfly-plus', 2, 2, 1, 1, 0, 'tor'],
    ['dragonfly-plus', 3, 1, 2, 1, 1, 'tor'], ['dragonfly-plus', 3, 2, 2, 1, 0, 'group'],
]

def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
    rounds = int(sys.argv[2]) if len(sys.argv) > 2 else 200
    rng = random.Random(seed)
    fails = 0
    checked = 0
    for i in range(rounds):
        topo = TOPOS[i % len(TOPOS)]
        session = gen_session(rng, topo)
        if session is None: continue
        expected = run_ref(session)
        got = run_engine(session)
        checked += 1
        if got != expected:
            fails += 1
            print(f'ROUND {i} topo={topo} MISMATCH')
            print('REQ:', json.dumps({'version': 2, 'sessions': [session]})[:2000])
            # find first difference
            print('EXP:', json.dumps(expected)[:1500])
            print('GOT:', json.dumps(got)[:1500])
            if fails >= 3: break
    print(f'checked={checked} fails={fails}')

if __name__ == '__main__':
    main()
